-- Staff-only event spending: each receipt photo carries its amount, and the
-- event total is always their sum. Like profile assets, receipt bytes live in
-- Postgres so the Go API authorizes every read and write without a browser
-- storage credential.
--
-- Receipt IDs are generated by the browser once per upload so retries reuse
-- the same row instead of storing a duplicate image.
create table csc.event_receipts (
  id uuid primary key,
  event_id uuid not null references csc.events(id),
  amount_cents bigint not null check (amount_cents between 0 and 10000000),
  media_type text not null check (media_type in ('image/jpeg', 'image/png')),
  bytes bytea not null check (octet_length(bytes) between 1 and 10485760),
  -- Actor IDs have no FK to Auth so records survive account removal.
  uploaded_by uuid not null,
  created_at timestamptz not null default now()
);
create index event_receipts_event_idx on csc.event_receipts (event_id, created_at, id);

revoke all on csc.event_receipts from public, anon, authenticated;
alter table csc.event_receipts enable row level security;
